// WS-04 Phase 2/3 milestones: classify documents that need attention.
// 'failed' documents are routed to the Auto Retry branch below (Progress.md
// Blockers #4: previously this workflow only surfaced them for a human).
// Documents stuck in 'queued'/'processing' for >15 minutes are a wedged
// worker/broker problem that re-dispatching the same pipeline wouldn't fix,
// so those are still only logged for a human, unchanged.
const STALE_THRESHOLD_MS = 15 * 60 * 1000;
const now = Date.now();
const flagged = [];

for (const item of $input.all()) {
  const doc = item.json;
  const updatedAtMs = new Date(doc.updatedAt).getTime();
  const isFailed = doc.status === 'failed';
  const isStuck = (doc.status === 'queued' || doc.status === 'processing') && (now - updatedAtMs) > STALE_THRESHOLD_MS;

  if (isFailed || isStuck) {
    flagged.push({
      json: {
        documentId: doc.id,
        status: doc.status,
        errorMessage: doc.errorMessage || null,
        retryCount: doc.retryCount ?? 0,
        reason: isFailed ? 'failed' : 'stuck_in_processing',
        updatedAt: doc.updatedAt,
      },
    });
  }
}

return flagged;

// Auto Retry uses neverError, so a 409 (retry budget exhausted, or the
// document already moved on before this ran) lands here as data, not a
// workflow failure. Log the outcome either way -- an exhausted document
// still needs a human, same as before this workflow could auto-retry.
const response = $input.item.json;
const statusCode = response.statusCode ?? response.status;
const body = response.body ?? response;

return {
  json: {
    documentId: body.document_id ?? body.documentId,
    statusCode,
    outcome: statusCode === 202 ? 'retried' : 'retry_budget_exhausted_or_conflict',
    retryCount: body.retry_count ?? null,
    detail: body.detail ?? null,
    at: $now.toISO(),
  },
};
